height = [[1]*n for _ in range(n)]
for r in range(1,n):
    for c in range(n):
        if grid[r][c] == grid[r-1][c]:
            height[r][c] = height[r-1][c]+1
answer = [0]*k
for top in range(n):
    upper = grid[top]
    for bottom in range(top,n):
        lower, heights = grid[bottom], height[bottom]
        need = bottom-top+1
        previous = -1
        seen = 0
        for c in range(n):
            value = upper[c]
            if value != lower[c]:
                previous = -1
                seen = 0
                continue
            if value != previous:
                previous = value
                seen = 0
            if heights[c] >= need:
                seen += 1
                answer[value-65] += seen
print('\n'.join(map(str,answer)))

